+        try (BufferedReader reader = new BufferedReader(new InputStreamReader(input, StandardCharsets.UTF_8))) {
+            String line = reader.readLine();
+            while (line != null) {
+                if (line.trim().startsWith("//") == false) {
+                    builder.append(line);
+                    builder.append('\n');
+                }
+                line = reader.readLine();
+            }
+            return builder.toString();
+        }
